{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Chain TVL Data",
    "operation": "add",
    "widgets_json": {
      "chains_highchart": {
        "name": "TVL by Chain (Highcharts)",
        "description": "Highcharts rendering of chain TVL.",
        "endpoint": "/chains-highchart",
        "type": "chart-highcharts",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": [
          {
            "paramName": "chain",
            "type": "text",
            "label": "Chain",
            "value": "Ethereum",
            "description": "Chain to chart."
          }
        ]
      },
      "gas_metric": {
        "name": "Gas Now",
        "description": "Current gas price snapshot.",
        "endpoint": "/gas-now",
        "type": "metric",
        "w": 5,
        "h": 4,
        "staleTime": 900000
      },
      "chains_table": {
        "name": "Top Chains by TVL",
        "description": "Current TVL of all chains from the desk aggregator.",
        "endpoint": "/chains-table",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "table": {
          "columnsDefs": [
            {
              "field": "name",
              "headerName": "Chain",
              "cellDataType": "text"
            },
            {
              "field": "tvl_usd",
              "headerName": "TVL ($)",
              "cellDataType": "number",
              "formatterFn": "int",
              "renderFn": "titleCase"
            },
            {
              "field": "change_1d",
              "headerName": "1d Change",
              "cellDataType": "number",
              "formatterFn": "percent",
              "renderFn": "greenRed"
            }
          ]
        }
      }
    }
  }
}

